import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring } from "remotion";
import { COLORS, FONTS, ENGRAVE_SHADOW } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

// Deterministic pseudo-random in [0,1) — same value on every render pass.
const rnd = (n: number): number => {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
};

const clamp = (v: number, lo: number, hi: number): number => Math.max(lo, Math.min(hi, v));
const num = (v: unknown, d: number): number => (typeof v === "number" && isFinite(v) ? v : d);

const PaperShardAssembly: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame: box }) => {
  const frame = useCurrentFrame();
  const dur = Math.max(1, Math.round((anim.end - anim.start) * fps));

  const src = String(anim.params?.src ?? "");
  const text = String(anim.text ?? "").trim();
  const hasText = text.length > 0;
  const scatter = clamp(num(anim.params?.scatter, 1), 0.2, 2);

  // ── Layout: the image is the subject, the headline sits beside it (wide
  //    frames) or under it (portrait). Nothing is ever clipped.
  const pad = Math.round(Math.min(box.width, box.height) * 0.06);
  const row = format !== "portrait" && hasText;

  const innerW = box.width - pad * 2;
  const gap = pad;
  const imgW = row ? (innerW - gap) * 0.58 : innerW;
  const imgH = row
    ? box.height - pad * 2
    : hasText
      ? (box.height - pad * 2) * (format === "half" ? 0.62 : 0.7)
      : box.height - pad * 2;
  const textW = row ? innerW - gap - imgW : imgW;

  // Type shrinks as the headline grows, so long copy wraps instead of overflowing.
  const fitW = row ? textW : imgW;
  const fontSize = Math.max(
    22,
    Math.min(
      row ? fitW * 0.2 : box.height * (format === "half" ? 0.085 : 0.075),
      (fitW * 1.9) / Math.max(6, text.length),
    ),
  );

  // ── Shard grid: roughly square scraps, capped so wide frames stay cheap.
  const cols = clamp(Math.round(num(anim.params?.cols, format === "landscape" ? 9 : 7)), 3, 14);
  const tileW = imgW / cols;
  const rows = clamp(Math.round(imgH / tileW), 2, Math.ceil(120 / cols));
  const tileH = imgH / rows;

  // Line-screen paper stand-in when the pipeline hands us no image.
  const placeholder = `repeating-linear-gradient(90deg, ${COLORS.vellum} 0px, ${COLORS.vellum} 7px, ${COLORS.papyrus} 7px, ${COLORS.papyrus} 14px)`;

  const settleFrames = Math.max(6, Math.round(fps * 0.7));
  const shards: React.ReactNode[] = [];

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const i = r * cols + c;
      const cx = (c + 0.5) / cols - 0.5;
      const cy = (r + 0.5) / rows - 0.5;
      // Centre scraps land first, edges trail — the image grows outward.
      const distN = Math.min(1, Math.hypot(cx, cy) / 0.7);
      const delay = (distN * 0.5 + rnd(i) * 0.5) * dur * 0.5;
      const p = spring({
        frame: frame - delay,
        fps,
        config: { damping: 18, stiffness: 140 },
        durationInFrames: settleFrames,
      });
      const inv = 1 - p;
      const ang = rnd(i + 91) * Math.PI * 2;
      const reach = (0.3 + rnd(i + 17) * 0.7) * Math.max(box.width, box.height) * 0.55 * scatter;

      shards.push(
        <div
          key={i}
          style={{
            position: "absolute",
            left: c * tileW,
            top: r * tileH,
            width: tileW + 1, // 1px overlap hides seams between settled scraps
            height: tileH + 1,
            overflow: "hidden",
            opacity: Math.min(1, p * 2.2),
            translate: `${(Math.cos(ang) * reach * inv).toFixed(2)}px ${(Math.sin(ang) * reach * inv).toFixed(2)}px`,
            rotate: `${((rnd(i + 53) - 0.5) * 70 * inv).toFixed(2)}deg`,
            scale: 1 + 0.25 * inv,
            boxShadow: inv > 0.02 ? `0 ${(7 * inv).toFixed(1)}px ${(20 * inv).toFixed(1)}px rgba(0,0,0,0.45)` : "none",
          }}
        >
          {src ? (
            <Img
              src={src}
              style={{
                position: "absolute",
                left: -c * tileW,
                top: -r * tileH,
                width: imgW,
                height: imgH,
                objectFit: "cover",
              }}
            />
          ) : (
            <div
              style={{
                position: "absolute",
                left: -c * tileW,
                top: -r * tileH,
                width: imgW,
                height: imgH,
                background: placeholder,
              }}
            />
          )}
        </div>,
      );
    }
  }

  const capDelay = dur * 0.42;
  const capIn = interpolate(frame, [capDelay, capDelay + Math.max(4, Math.round(fps * 0.25))], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const spine = Math.max(6, Math.round(fontSize * 0.09));

  const headline = hasText ? (
    <div
      style={{
        width: textW,
        opacity: capIn,
        translate: row ? `${((1 - capIn) * -spine * 4).toFixed(1)}px 0px` : `0px ${((1 - capIn) * spine * 2).toFixed(1)}px`,
        borderLeft: row ? `${spine}px solid ${COLORS.teal}` : undefined,
        borderTop: row ? undefined : `${spine}px solid ${COLORS.teal}`,
        paddingLeft: row ? spine * 1.6 : 0,
        paddingTop: row ? 0 : spine * 1.4,
        boxSizing: "border-box",
      }}
    >
      <div
        style={{
          fontFamily: FONTS.display,
          fontWeight: FONTS.displayWeight,
          fontSize,
          lineHeight: 1.04,
          letterSpacing: "-0.02em",
          textTransform: "uppercase",
          color: dark ? COLORS.textOnDark : COLORS.textOnLight,
          textShadow: ENGRAVE_SHADOW,
          textAlign: row ? "left" : "center",
          wordBreak: "break-word",
          overflowWrap: "anywhere",
        }}
      >
        {text}
      </div>
    </div>
  ) : null;

  return (
    <AbsoluteFill
      style={{
        fontFamily: FONTS.body,
        alignItems: "center",
        justifyContent: "center",
        flexDirection: row ? "row" : "column",
        gap,
        padding: pad,
        boxSizing: "border-box",
      }}
    >
      <div style={{ position: "relative", width: imgW, height: imgH, flexShrink: 0 }}>{shards}</div>
      {headline}
    </AbsoluteFill>
  );
};

export default PaperShardAssembly;
